function rm_month_valid(string $value): bool { return (bool) preg_match('/^\d{4}-(0[1-9]|1[0-2])$/', $value); }
function rm_number(mixed $value): string { return number_format((float)$value, 0, ',', '.'); }
function rm_pdf_escape(mixed $value): string {
    $value = iconv('UTF-8', 'Windows-1252//TRANSLIT//IGNORE', (string)$value);
    return str_replace(['\\','(',')'], ['\\\\','\\(','\\)'], (string)$value);
}
function rm_pdf(array $lines, string $filename): never {
    $chunks=array_chunk($lines ?: ['Tidak ada data.'],43); $objects=[1=>'<< /Type /Catalog /Pages 2 0 R >>',3=>'<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>']; $kids=[]; $number=4;
    foreach($chunks as $index=>$chunk){$page=$number++;$content=$number++;$kids[]="$page 0 R";$command="BT /F1 8 Tf 28 560 Td 11.5 TL\n";foreach($chunk as $line)$command.='('.rm_pdf_escape($line).") Tj T*\n";$command.='(Halaman '.($index+1).' dari '.count($chunks).") Tj\nET";$objects[$page]="<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /Font << /F1 3 0 R >> >> /Contents $content 0 R >>";$objects[$content]="<< /Length ".strlen($command)." >>\nstream\n$command\nendstream";}
    $objects[2]='<< /Type /Pages /Kids ['.implode(' ',$kids).'] /Count '.count($kids).' >>';ksort($objects);$pdf="%PDF-1.4\n";$offset=[0];foreach($objects as $id=>$object){$offset[$id]=strlen($pdf);$pdf.="$id 0 obj\n$object\nendobj\n";}$xref=strlen($pdf);$max=max(array_keys($objects));$pdf.="xref\n0 ".($max+1)."\n0000000000 65535 f \n";for($i=1;$i<=$max;$i++)$pdf.=sprintf('%010d 00000 n ',$offset[$i])."\n";$pdf.="trailer\n<< /Size ".($max+1)." /Root 1 0 R >>\nstartxref\n$xref\n%%EOF";
    header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.$filename.'.pdf"');header('Content-Length: '.strlen($pdf));header('Cache-Control: no-store');echo $pdf;exit;
}
function rm_locked(PDO $db,int $guruId,string $date): bool {
    $stmt=$db->prepare("SELECT EXISTS(SELECT 1 FROM validasi_rekap_mengajar v JOIN users u ON u.id=v.divalidasi_oleh AND u.role_id=1 WHERE v.guru_id=? AND v.periode_bulan=DATE_FORMAT(?,'%Y-%m-01'))");$stmt->execute([$guruId,$date]);return (bool)$stmt->fetchColumn();
}

$ownGuruId=0;
if(!$isAdmin){$stmt=$db->prepare('SELECT id FROM guru WHERE user_id=?');$stmt->execute([$_SESSION['user_id']]);$ownGuruId=(int)$stmt->fetchColumn();if(!$ownGuruId){http_response_code(403);exit('Profil Guru tidak ditemukan.');}}
$month=trim($_GET['bulan']??date('Y-m'));if(!rm_month_valid($month))$month=date('Y-m');
