    try{
        $action=$_POST['action']??'';
        if($action==='validate'){
            if(!$isAdmin)throw new InvalidArgumentException('Validasi hanya dapat dilakukan oleh admin.');
            $guruId=(int)($_POST['guru_id']??0);$period=trim($_POST['periode_bulan']??'');if($guruId<1||!rm_month_valid($period))throw new InvalidArgumentException('Data validasi tidak valid.');$startPeriod=$period.'-01';$endPeriod=date('Y-m-t',strtotime($startPeriod));
            $stmt=$db->prepare('SELECT COALESCE(SUM(r.jumlah_jp),0) FROM rekap_mengajar r JOIN pengajaran p ON p.id=r.pengajaran_id WHERE p.guru_id=? AND r.tanggal BETWEEN ? AND ?');$stmt->execute([$guruId,$startPeriod,$endPeriod]);$total=(float)$stmt->fetchColumn();if($total<=0)throw new InvalidArgumentException('Belum ada JP yang dapat divalidasi.');
            $stmt=$db->prepare('INSERT INTO validasi_rekap_mengajar(guru_id,periode_bulan,total_jp,divalidasi_oleh,divalidasi_pada) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE total_jp=VALUES(total_jp),divalidasi_oleh=VALUES(divalidasi_oleh),divalidasi_pada=NOW()');$stmt->execute([$guruId,$startPeriod,$total,$_SESSION['user_id']]);catat_log($_SESSION['user_id'],"Admin memvalidasi rekap guru ID $guruId periode $period sejumlah $total JP");$_SESSION['flash_success']='Rekap bulanan berhasil divalidasi admin dan dikunci.';
        }elseif($action==='revoke'){
            if(!$isAdmin)throw new InvalidArgumentException('Aksi tidak diizinkan.');$guruId=(int)($_POST['guru_id']??0);$period=trim($_POST['periode_bulan']??'');if($guruId<1||!rm_month_valid($period))throw new InvalidArgumentException('Data validasi tidak valid.');
            $stmt=$db->prepare('DELETE FROM validasi_rekap_mengajar WHERE guru_id=? AND periode_bulan=?');$stmt->execute([$guruId,$period.'-01']);if(!$stmt->rowCount())throw new InvalidArgumentException('Validasi tidak ditemukan.');catat_log($_SESSION['user_id'],"Admin membatalkan validasi guru ID $guruId periode $period");$_SESSION['flash_success']='Validasi dibatalkan. Setelah koreksi, admin perlu memvalidasi kembali.';
        }elseif(in_array($action,['save','delete'],true)){
            if(!$isAdmin)throw new InvalidArgumentException('Aksi tidak diizinkan.');
            if($action==='delete'){
                $id=(int)($_POST['id']??0);$stmt=$db->prepare('SELECT p.guru_id,r.tanggal FROM rekap_mengajar r JOIN pengajaran p ON p.id=r.pengajaran_id WHERE r.id=?');$stmt->execute([$id]);$old=$stmt->fetch();if(!$old)throw new InvalidArgumentException('Catatan tidak ditemukan.');if(rm_locked($db,(int)$old['guru_id'],$old['tanggal']))throw new InvalidArgumentException('Rekap bulan ini sudah divalidasi dan dikunci.');$db->prepare('DELETE FROM rekap_mengajar WHERE id=?')->execute([$id]);catat_log($_SESSION['user_id'],"Menghapus realisasi mengajar ID: $id");$_SESSION['flash_success']='Catatan JP berhasil dihapus.';
            }else{
                $id=(int)($_POST['id']??0);$teachingId=(int)($_POST['pengajaran_id']??0);$date=trim($_POST['tanggal']??'');$session=$_POST['jenis_sesi']??'';$first=(int)($_POST['jam_ke_mulai']??0);$last=(int)($_POST['jam_ke_selesai']??0);$validDate=DateTime::createFromFormat('!Y-m-d',$date);
                if(!$validDate||$validDate->format('Y-m-d')!==$date||!in_array($session,['Pagi','Siang'],true)||$first<1||$first>6||$last<$first||$last>6)throw new InvalidArgumentException('Tanggal, sesi, atau rentang jam pelajaran tidak valid.');
                $stmt=$db->prepare('SELECT guru_id FROM pengajaran WHERE id=?');$stmt->execute([$teachingId]);$guruId=(int)$stmt->fetchColumn();if(!$guruId)throw new InvalidArgumentException('Pengajaran tidak ditemukan.');if(rm_locked($db,$guruId,$date))throw new InvalidArgumentException('Rekap guru pada bulan ini sudah divalidasi dan dikunci.');
                if($id){$stmt=$db->prepare('SELECT p.guru_id,r.tanggal FROM rekap_mengajar r JOIN pengajaran p ON p.id=r.pengajaran_id WHERE r.id=?');$stmt->execute([$id]);$old=$stmt->fetch();if(!$old)throw new InvalidArgumentException('Catatan tidak ditemukan.');if(rm_locked($db,(int)$old['guru_id'],$old['tanggal']))throw new InvalidArgumentException('Catatan lama berada pada bulan yang dikunci.');}
                $overlap=$db->prepare('SELECT COUNT(*) FROM rekap_mengajar r JOIN pengajaran p ON p.id=r.pengajaran_id WHERE p.guru_id=? AND r.tanggal=? AND r.jenis_sesi=? AND r.id<>? AND r.jam_ke_mulai<=? AND r.jam_ke_selesai>=?');$overlap->execute([$guruId,$date,$session,$id,$last,$first]);if((int)$overlap->fetchColumn()>0)throw new InvalidArgumentException('Guru sudah memiliki catatan yang bertumpuk pada hari, sesi, dan jam tersebut.');
                $jp=$last-$first+1;$legacyStart=sprintf('%02d:00',$first);$legacyEnd=sprintf('%02d:00',$last+1);$legacySession="$session - Jam ke-$first s.d. $last";
                if($id){$stmt=$db->prepare('UPDATE rekap_mengajar SET pengajaran_id=?,tanggal=?,jenis_sesi=?,jam_ke_mulai=?,jam_ke_selesai=?,jam_mulai=?,jam_selesai=?,sesi=?,jumlah_jp=? WHERE id=?');$stmt->execute([$teachingId,$date,$session,$first,$last,$legacyStart,$legacyEnd,$legacySession,$jp,$id]);catat_log($_SESSION['user_id'],"Mengubah realisasi mengajar ID: $id");$_SESSION['flash_success']='Catatan JP berhasil diperbarui.';}
                else{$stmt=$db->prepare('INSERT INTO rekap_mengajar(pengajaran_id,tanggal,jenis_sesi,jam_ke_mulai,jam_ke_selesai,jam_mulai,jam_selesai,sesi,jumlah_jp,dibuat_oleh) VALUES(?,?,?,?,?,?,?,?,?,?)');$stmt->execute([$teachingId,$date,$session,$first,$last,$legacyStart,$legacyEnd,$legacySession,$jp,$_SESSION['user_id']]);catat_log($_SESSION['user_id'],'Menambahkan realisasi mengajar ID: '.$db->lastInsertId());$_SESSION['flash_success']="$jp JP berhasil dicatat.";}
            }
        }else throw new InvalidArgumentException('Aksi tidak dikenali.');
    }catch(InvalidArgumentException $e){$_SESSION['flash_error']=$e->getMessage();}catch(Throwable $e){error_log('Rekap mengajar: '.$e->getMessage());$_SESSION['flash_error']='Data gagal diproses. Pastikan migrasi terbaru sudah dijalankan.';}
    redirect($pageName.'?'.http_build_query(array_filter(['bulan'=>$month,'guru_id'=>$teacherFilter?:null,'kelas_id'=>$classFilter?:null,'mapel_id'=>$subjectFilter?:null])));
}

$where=['r.tanggal BETWEEN ? AND ?'];$params=[$monthStart,$monthEnd];foreach([['p.guru_id',$teacherFilter],['p.kelas_id',$classFilter],['p.mapel_id',$subjectFilter]] as [$column,$value])if($value){$where[]="$column=?";$params[]=$value;}$whereSql=implode(' AND ',$where);
