$stmt=$db->prepare($select.$joins.' WHERE '.$whereSql.' ORDER BY g.nama_lengkap,m.nama_mapel,r.tanggal,r.jenis_sesi,r.jam_ke_mulai');$stmt->execute($params);$details=$stmt->fetchAll();
$stmt=$db->prepare('SELECT g.id guru_id,g.nama_lengkap,m.id mapel_id,m.nama_mapel,SUM(r.jumlah_jp) total_jp'.$joins.' WHERE '.$whereSql.' GROUP BY g.id,g.nama_lengkap,m.id,m.nama_mapel ORDER BY g.nama_lengkap,m.nama_mapel');$stmt->execute($params);$monthly=$stmt->fetchAll();
$stmt=$db->prepare('SELECT r.tanggal,g.id guru_id,g.nama_lengkap,SUM(r.jumlah_jp) total_jp'.$joins.' WHERE '.$whereSql.' GROUP BY r.tanggal,g.id,g.nama_lengkap ORDER BY r.tanggal DESC,g.nama_lengkap');$stmt->execute($params);$daily=$stmt->fetchAll();
