    if($_GET['format']==='excel'){header('Content-Type: application/vnd.ms-excel; charset=UTF-8');header('Content-Disposition: attachment; filename="'.$filename.'.xls"');header('Cache-Control: no-store');echo "\xEF\xBB\xBF";?><table border="1"><tr><th colspan="10"><?= sanitize($title) ?></th></tr><tr><th>No</th><th>Hari</th><th>Tanggal</th><th>Guru</th><th>Mapel</th><th>Kelas</th><th>Sesi</th><th>Jam Ke</th><th>JP</th><th>Status</th></tr><?php foreach($details as $i=>$r):?><tr><td><?= $i+1 ?></td><td><?= $days[date('l',strtotime($r['tanggal']))] ?></td><td><?= date('d/m/Y',strtotime($r['tanggal'])) ?></td><td><?= sanitize($r['nama_lengkap']) ?></td><td><?= sanitize($r['nama_mapel']) ?></td><td><?= sanitize($r['nama_kelas']) ?></td><td><?= sanitize($r['jenis_sesi']) ?></td><td><?= (int)$r['jam_ke_mulai'] ?>-<?= (int)$r['jam_ke_selesai'] ?></td><td><?= (float)$r['jumlah_jp'] ?></td><td><?= isset($validationByTeacher[(int)$r['guru_id']])?'Divalidasi Admin':'Belum Divalidasi' ?></td></tr><?php endforeach?><tr><th colspan="8">TOTAL JP</th><th><?= $totalActual ?></th><th></th></tr><tr></tr><tr><th>Guru</th><th>Mata Pelajaran</th><th>Total JP Bulan</th><th>Status</th></tr><?php foreach($monthly as $r):?><tr><td><?= sanitize($r['nama_lengkap']) ?></td><td><?= sanitize($r['nama_mapel']) ?></td><td><?= (float)$r['total_jp'] ?></td><td><?= isset($validationByTeacher[(int)$r['guru_id']])?'Divalidasi Admin':'Belum Divalidasi' ?></td></tr><?php endforeach?></table><?php exit;}
    $lines=[$title,'Periode: '.date('m/Y',strtotime($monthStart)),'Total: '.rm_number($totalActual).' JP',str_repeat('-',125),sprintf('%-3s %-10s %-20s %-22s %-13s %-12s %4s','No','Tanggal','Guru','Mata Pelajaran','Kelas','Sesi/Jam','JP'),str_repeat('-',125)];$short=static fn($v,$w)=>function_exists('mb_strimwidth')?mb_strimwidth($v,0,$w,'..','UTF-8'):substr($v,0,$w);foreach($details as $i=>$r)$lines[]=sprintf('%-3d %-10s %-20s %-22s %-13s %-12s %4s',$i+1,date('d/m/Y',strtotime($r['tanggal'])),$short($r['nama_lengkap'],20),$short($r['nama_mapel'],22),$short($r['nama_kelas'],13),$r['jenis_sesi'].' '.$r['jam_ke_mulai'].'-'.$r['jam_ke_selesai'],rm_number($r['jumlah_jp']));$lines[]=str_repeat('-',125);$lines[]='TOTAL '.rm_number($totalActual).' JP';$lines[]='';$lines[]='RINGKASAN PER GURU / MATA PELAJARAN';foreach($monthly as $r)$lines[]=$r['nama_lengkap'].' | '.$r['nama_mapel'].' | '.rm_number($r['total_jp']).' JP | '.(isset($validationByTeacher[(int)$r['guru_id']])?'Divalidasi Admin':'Belum Divalidasi');rm_pdf($lines,$filename);
