<section class="card border-0 shadow-sm mb-4"><div class="card-body"><form method="get" class="row g-2 align-items-end"><div class="col-6 col-md"><label class="form-label small">Bulan</label><input type="month" name="bulan" class="form-control" value="<?= sanitize($month) ?>"></div><?php if($isAdmin):?><div class="col-6 col-md"><label class="form-label small">Guru</label><select name="guru_id" class="form-select"><option value="0">Semua Guru</option><?php foreach($teachers as $g):?><option value="<?= (int)$g['id'] ?>" <?= $teacherFilter===(int)$g['id']?'selected':'' ?>><?= sanitize($g['nama_lengkap']) ?></option><?php endforeach?></select></div><?php endif?><div class="col-6 col-md"><label class="form-label small">Kelas</label><select name="kelas_id" id="rmFilterClass" class="form-select"><option value="0">Semua Kelas</option><?php foreach($classes as $k):?><option value="<?= (int)$k['id'] ?>" <?= $classFilter===(int)$k['id']?'selected':'' ?>><?= sanitize($k['nama_kelas']) ?></option><?php endforeach?></select></div><div class="col-6 col-md"><label class="form-label small">Mapel</label><select name="mapel_id" id="rmFilterSubject" class="form-select"><option value="0">Semua Mapel</option><?php foreach($subjects as $m):?><option value="<?= (int)$m['id'] ?>" <?= $subjectFilter===(int)$m['id']?'selected':'' ?>><?= sanitize($m['nama_mapel']) ?></option><?php endforeach?></select></div><div class="col-md-auto"><button class="btn btn-primary w-100">Tampilkan</button></div></form></div></section>
<div class="row g-3 mb-4"><?php foreach([['Total JP Bulan',rm_number($totalActual),'text-primary'],['Guru Aktif',$teacherCount,''],['Hari Tercatat',$dayCount,''],['Status',(!$isAdmin&&isset($validationByTeacher[$ownGuruId]))?'Divalidasi':'Berjalan',(!$isAdmin&&isset($validationByTeacher[$ownGuruId]))?'text-success':'text-warning']] as $c):?><div class="col-6 col-lg-3"><div class="card border-0 shadow-sm h-100"><div class="card-body"><small class="text-muted"><?= sanitize($c[0]) ?></small><h4 class="fw-bold <?= $c[2] ?>"><?= sanitize($c[1]) ?></h4></div></div></div><?php endforeach?></div>
