<section class="card border-0 shadow-sm mb-4"><div class="card-body"><div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-3"><div><h6 class="fw-bold mb-0">Rekap Bulanan per Guru dan Mata Pelajaran</h6><small class="text-muted">Dasar ringkasan JP untuk bagian keuangan<?= $isAdmin&&!$canAdminValidate?' · Reset filter kelas/mapel untuk melakukan validasi':'' ?></small></div><div class="rm-export"><a class="btn btn-sm btn-success" href="?<?= sanitize(http_build_query(array_merge($state,['format'=>'excel']))) ?>"><i class="fa-solid fa-file-excel me-1"></i>Excel</a> <a class="btn btn-sm btn-danger" href="?<?= sanitize(http_build_query(array_merge($state,['format'=>'pdf']))) ?>"><i class="fa-solid fa-file-pdf me-1"></i>PDF</a></div></div><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Guru</th><th>Mata Pelajaran</th><th class="text-end">Total JP</th><th>Status Bulanan</th><?php if($isAdmin):?><th>Aksi</th><?php endif?></tr></thead><tbody><?php foreach($monthly as $r):$v=$validationByTeacher[(int)$r['guru_id']]??null;?><tr><td><strong><?= sanitize($r['nama_lengkap']) ?></strong></td><td><?= sanitize($r['nama_mapel']) ?></td><td class="text-end fw-bold"><?= rm_number($r['total_jp']) ?> JP</td><td><span class="badge rm-status <?= $v?'bg-success':'bg-warning text-dark' ?>"><?= $v?'Divalidasi Admin':'Belum Divalidasi' ?></span></td><?php if($isAdmin):?><td><?php if($v):?><form method="post" onsubmit="return confirm('Batalkan validasi agar data dapat dikoreksi? Setelah koreksi, admin perlu memvalidasi kembali.')"><input type="hidden" name="csrf_token" value="<?= sanitize($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="revoke"><input type="hidden" name="guru_id" value="<?= (int)$r['guru_id'] ?>"><input type="hidden" name="periode_bulan" value="<?= sanitize($month) ?>"><button class="btn btn-sm btn-outline-warning">Buka Koreksi</button></form><?php else:?><form method="post" onsubmit="return confirm('Validasi seluruh rekap JP guru ini untuk bulan yang dipilih?')"><input type="hidden" name="csrf_token" value="<?= sanitize($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="validate"><input type="hidden" name="guru_id" value="<?= (int)$r['guru_id'] ?>"><input type="hidden" name="periode_bulan" value="<?= sanitize($month) ?>"><button class="btn btn-sm btn-success" <?= !$canAdminValidate?'disabled title="Reset filter kelas dan mapel terlebih dahulu"':'' ?>><i class="fa-solid fa-check me-1"></i>Validasi</button></form><?php endif?></td><?php endif?></tr><?php endforeach;if(!$monthly):?><tr><td colspan="<?= $isAdmin?5:4 ?>" class="text-center text-muted py-4">Belum ada data pada bulan ini.</td></tr><?php endif?></tbody></table></div></div></section>
<section class="card border-0 shadow-sm mb-4"><div class="card-body"><h6 class="fw-bold">Rincian Harian</h6><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>Hari/Tanggal</th><?php if($isAdmin):?><th>Guru</th><?php endif?><th>Mapel / Kelas</th><th>Sesi</th><th>Jam Ke</th><th class="text-end">JP</th><?php if($isAdmin):?><th>Aksi</th><?php endif?></tr></thead><tbody><?php foreach($details as $r):$locked=isset($validationByTeacher[(int)$r['guru_id']]);?><tr><td><?= $days[date('l',strtotime($r['tanggal']))] ?><br><small><?= date('d/m/Y',strtotime($r['tanggal'])) ?></small></td><?php if($isAdmin):?><td><?= sanitize($r['nama_lengkap']) ?></td><?php endif?><td><?= sanitize($r['nama_mapel']) ?><br><small><?= sanitize($r['nama_kelas']) ?></small></td><td><span class="badge <?= $r['jenis_sesi']==='Pagi'?'bg-info text-dark':'bg-primary' ?>"><?= sanitize($r['jenis_sesi']) ?></span></td><td><?= (int)$r['jam_ke_mulai'] ?>–<?= (int)$r['jam_ke_selesai'] ?></td><td class="text-end fw-bold"><?= rm_number($r['jumlah_jp']) ?></td><?php if($isAdmin):?><td><?php if($locked):?><span class="text-success small"><i class="fa-solid fa-lock"></i> Terkunci</span><?php else:?><a class="btn btn-sm btn-outline-primary" href="?<?= sanitize(http_build_query(array_merge($state,['edit_id'=>$r['id']]))) ?>">Ubah</a> <form method="post" class="d-inline" onsubmit="return confirm('Hapus catatan JP ini?')"><input type="hidden" name="csrf_token" value="<?= sanitize($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="btn btn-sm btn-outline-danger">Hapus</button></form><?php endif?></td><?php endif?></tr><?php endforeach;if(!$details):?><tr><td colspan="<?= $isAdmin?7:6 ?>" class="text-center text-muted py-4">Belum ada aktivitas mengajar.</td></tr><?php endif?></tbody></table></div></div></section>
<section class="card border-0 shadow-sm"><div class="card-body"><h6 class="fw-bold">Monitoring JP per Hari</h6><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Tanggal</th><?php if($isAdmin):?><th>Guru</th><?php endif?><th class="text-end">JP</th></tr></thead><tbody><?php foreach($daily as $r):?><tr><td><?= $days[date('l',strtotime($r['tanggal']))].', '.date('d/m/Y',strtotime($r['tanggal'])) ?></td><?php if($isAdmin):?><td><?= sanitize($r['nama_lengkap']) ?></td><?php endif?><td class="text-end fw-bold"><?= rm_number($r['total_jp']) ?></td></tr><?php endforeach?></tbody></table></div></div></section>
</main></div><script>(()=>{const rows=<?= json_encode($teachings,JSON_UNESCAPED_UNICODE|JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>,option=(value,label)=>{const o=document.createElement('option');o.value=value;o.textContent=label;return o};const a=document.getElementById('rmStart'),b=document.getElementById('rmEnd'),j=document.getElementById('rmJp');if(a){const calc=()=>{if(+b.value<+a.value)b.value=a.value;j.value=(+b.value-+a.value+1)+' JP'};a.addEventListener('change',calc);b.addEventListener('change',calc);calc()}const filterClass=document.getElementById('rmFilterClass'),filterSubject=document.getElementById('rmFilterSubject');if(filterClass&&filterSubject&&<?= $isAdmin?'false':'true' ?>){const selectedSubject=<?= $subjectFilter ?>,loadFilterSubjects=()=>{filterSubject.replaceChildren(option(0,'Semua Mapel'));const seen=new Set;rows.filter(r=>!+filterClass.value||+r.kelas_id===+filterClass.value).forEach(r=>{if(!seen.has(+r.mapel_id)){seen.add(+r.mapel_id);filterSubject.append(option(r.mapel_id,r.nama_mapel))}});if([...filterSubject.options].some(o=>+o.value===selectedSubject))filterSubject.value=selectedSubject};filterClass.addEventListener('change',()=>{loadFilterSubjects();filterSubject.value='0'});loadFilterSubjects()}const teacher=document.getElementById('rmTeacher'),subject=document.getElementById('rmSubject'),teaching=document.getElementById('rmTeaching');if(!teacher)return;const selected=<?= (int)($edit['pengajaran_id']??0) ?>,current=rows.find(r=>+r.id===selected);const loadSubjects=()=>{subject.replaceChildren(option('','Pilih mata pelajaran'));teaching.replaceChildren(option('','Pilih mapel dahulu'));teaching.disabled=true;const seen=new Set;rows.filter(r=>+r.guru_id===+teacher.value).forEach(r=>{if(!seen.has(+r.mapel_id)){seen.add(+r.mapel_id);subject.append(option(r.mapel_id,r.nama_mapel))}});subject.disabled=!teacher.value;if(current&&+current.guru_id===+teacher.value)subject.value=current.mapel_id;loadClasses()};const loadClasses=()=>{teaching.replaceChildren(option('','Pilih kelas'));rows.filter(r=>+r.guru_id===+teacher.value&&+r.mapel_id===+subject.value).forEach(r=>teaching.append(option(r.id,r.nama_kelas+' · '+r.semester+' '+r.tahun_ajaran)));teaching.disabled=!subject.value;if(current&&+current.guru_id===+teacher.value&&+current.mapel_id===+subject.value)teaching.value=current.id};teacher.addEventListener('change',loadSubjects);subject.addEventListener('change',loadClasses);if(current){teacher.value=current.guru_id;loadSubjects()}})()</script><?php require_once __DIR__.'/footer.php'; ?>
